  function Get_OTP(){
	//alert('Yes');
	var otpmobile = document.getElementById("phone").value;
	
	if(otpmobile=='') {
     alert("Please Enter Contact Number.");
     return false;
     }
	 $.ajax({
 type: "POST",
 url: "api/save_all_data.php",
 data: {otpmobile: otpmobile},
 
 success: function(data) {
 alert(data);
 },
 error: function(xhr, status, error) {
 console.error(xhr);
 }
 });
}


 function varify_OTP(){
	
	//alert('Yes');
	var verfyotp = document.getElementById("otp").value;
	
	
	 $.ajax({
 type: "POST",
 url: "api/otp.php",
 data: {verfyotp: verfyotp},
 
success: function(data) {


  if(data=='match')
 {
	$( "#formPromotion" ).submit();
	}else{
		
	alert('Your OTP did not match. please retry again.');
	return false;
	}   
 
 },

 });
}  



