function formCheck0() {
var fname = document.getElementById('name');
var gender = document.getElementsByName('gender');
var genValue = false;
for(var i=0; i<gender.length;i++){
if(gender[i].checked == true){genValue = true;}}

var organization = document.getElementById('organization');var email = document.getElementById('email');var mobile = document.getElementById('phone');var service = document.getElementById('service');var city = document.getElementById('formCity');var area = document.getElementById('center');var reg = /^([A-Za-z0-9_\-\.])+\@([A-Za-z0-9_\-\.])+\.([A-Za-z]{2,4})$/;var address=true;
if (email.value.trim() != ""){var address = email.value.trim();}
var charreg = /^[a-zA-Z\_ ]+$/g;var charregl = /^[a-zA-Z\_]+$/g;
if (fname.value.trim() == '' || fname.value.trim() == "Name"){alert('Please Enter Full Name');fname.focus();return false;}
else if (charreg.test(fname.value.trim())== false ) {alert('Please Enter Valid Full Name');fname.focus();return false;}
else if (organization.value.trim() == "" || organization.value.trim() == null) {alert("Please Enter Organization Name");organization.focus();return false;}


if(!genValue){alert("Please Choose the gender");gender.focus();return false;}

if (mobile.value.trim() == "" || mobile.value.trim() == "Mobile"){alert('Please Enter Contact Number');mobile.focus();return false;} 
 
else if (mobile.value.trim().length != 10) {alert('Please Enter Valid Contact Number with 10 Digits');mobile.focus();return false;}
else if (isNaN(mobile.value.trim())) {alert("Contact Number Only Accept Numeric Digits");mobile.focus();return false;}
else if ((mobile.value.trim() == 1234567890) || (mobile.value.trim() == 1234512345)) {alert("Please Enter Valid Contact Number");mobile.focus();return false;}
else if (mobile.value.trim().charAt(0) == '0') {alert("Please Enter Valid Contact Number");mobile.focus();return false;}

else if (email.value.trim() == "" || email.value.trim() == null) {alert("Please Enter Email Address");email.focus();return false;}
else if (reg.test(address) == false && email.value.trim() != "") {alert('Please Enter Valid Email Address');email.focus();return false;}

else if (service.value.trim() == "" || service.value.trim() == null) {alert("Please Select Service");service.focus();return false;}
else if (city.value.trim() == '' || city.value.trim() == null) {alert("Please Select City");city.focus();return false;}
else if (area.value.trim() == '' || area.value.trim() == null) {alert("Please Select Area");area.focus();return false;}
else {
	//varify_OTP();
	document.getElementById("sb_btn").disabled = true;document.myform.submit();
	}
}
