(function() {
  var hasInteracted = false;
  var delay = 30000; // Time in ms (30 seconds)

  function markInteracted() {
    hasInteracted = true;
    window.removeEventListener('click', markInteracted);
    window.removeEventListener('scroll', markInteracted);
    window.removeEventListener('keydown', markInteracted);
    window.removeEventListener('mousemove', markInteracted);
  }

  window.addEventListener('click', markInteracted);
  window.addEventListener('scroll', markInteracted);
  window.addEventListener('keydown', markInteracted);
  window.addEventListener('mousemove', markInteracted);

  setTimeout(function() {
    if (!hasInteracted) {
      window.dataLayer = window.dataLayer || [];
      window.dataLayer.push({
        event: 'no_click_scroll_detected',
        delayDuration: delay
      });
      console.log("No interaction detected within delay time.");
    }
  }, delay);
})();


/* --- Inline JS --- */

(function() {
  var scrollPoints = [25, 50, 75, 100]; // % thresholds
  var triggered = {};

  function checkScrollDepth() {
    var scrollTop = window.scrollY || window.pageYOffset;
    var docHeight = Math.max(document.body.scrollHeight, document.documentElement.scrollHeight);
    var winHeight = window.innerHeight;
    var scrollPercent = Math.round((scrollTop + winHeight) / docHeight * 100);

    scrollPoints.forEach(function(point) {
      if (scrollPercent >= point && !triggered[point]) {
        triggered[point] = true;

        window.dataLayer = window.dataLayer || [];
        window.dataLayer.push({
          event: 'scroll_depth',
          scrollPercent: point
        });

        console.log('Scroll depth reached:', point + '%');
      }
    });
  }

  window.addEventListener('scroll', checkScrollDepth);
})();


