$("#formCity").change(function () {
var url = "https://www.vlccwellness.com/India/promotion-page/";var city = $("#formCity").val();var service = $("#promotion").val()
if (city == "") {alert("Please Select a City");
return false;}
var post_data = "action=getFormCentersfromCity&city=" + city + "&service=" + service;
$.ajax({
type: "POST",
url: url + "api/ajax_action.php",
data: post_data,
success: function (result) {
$("#center").html(result);}
});});

